unitTests:
TEST("rounds up") { CHECK_EQ(roundToInt(2.7), 3); }
TEST("rounds down") { CHECK_EQ(roundToInt(2.2), 2); }
TEST("half rounds away from zero") { CHECK_EQ(roundToInt(2.5), 3); }
TEST("negative numbers") { CHECK_EQ(roundToInt(-2.7), -3); CHECK_EQ(roundToInt(-2.2), -2); }

